solid.fragmentPars:
uniform highp sampler2D lookSettings;

flat varying float vLookId;
varying vec3 vLookInfo;
varying vec2 vLookUv;
varying vec3 vLookWorld;
varying vec3 vLookWN;
varying vec3 vS0;
varying vec3 vS1;
varying vec4 vS2;
varying vec2 vS3;
#define s0 vS0
#define s1 vS1
#define s2 vS2
#define s3 vS3
uniform float lookView;
uniform float lookDebug;
// the uv's change across the pixel, worked out once where every pixel of the quad runs it, so a picture read inside a
// look's branch still knows its sharpness
vec2 lookGx, lookGy;

float kh(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float kh1(float x) { return fract(sin(x * 91.7) * 43758.5453); }
float kn(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(kh(i), kh(i + vec2(1, 0)), u.x), mix(kh(i + vec2(0, 1)), kh(i + vec2(1, 1)), u.x), u.y);
}
float kfbm(vec2 p) {
  float a = 0.5, s = 0.0;
  for (int i = 0; i < 5; i++) { s += a * kn(p); p = p * 2.03 + 17.1; a *= 0.5; }
  return s / 0.97;
}
float kfbm4(vec2 p) {
  float a = 0.5, s = 0.0;
  for (int i = 0; i < 4; i++) { s += a * kn(p); p = p * 2.03 + 17.1; a *= 0.5; }
  return s;
}
// a feature f metres across fades to its mean where it is finer than a pixel
float kfade(float f) { vec2 fw = abs(lookGx) + abs(lookGy); return clamp(1.5 - (fw.x + fw.y) / f, 0.0, 1.0); }
// cells of jittered seeds: the distance to the nearest, its number (0 to 1), and how far the second is past it
float kvor(vec2 p, out float id, out float edge) {
  vec2 i = floor(p), f = fract(p);
  float d1 = 8.0, d2 = 8.0;
  vec2 best = vec2(0.0);
  for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) {
    vec2 o = vec2(x, y);
    vec2 c = i + o;
    vec2 r = o + vec2(kh(c), kh(c + 7.3)) - f;
    float d = dot(r, r);
    if (d < d1) { d2 = d1; d1 = d; best = c; } else if (d < d2) { d2 = d; }
  }
  id = kh(best + 3.7);
  edge = sqrt(d2) - sqrt(d1);
  return sqrt(d1);
}
// a dimple field: the distance to the nearest of jittered cells' seeds
float kcell(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  float d = 8.0;
  for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) {
    vec2 o = vec2(x, y);
    vec2 r = o + vec2(kh(i + o), kh(i + o + 7.3)) - f;
    d = min(d, dot(r, r));
  }
  return sqrt(d);
}
// courses: the row along v, the piece in it along u (each row offset), where in the piece (0 to 1 each way)
vec4 kcourse(vec2 uv, float row, float wide, float jitter, float seed, out vec2 id) {
  float r = floor(uv.y / row);
  float shift = kh1(r + seed) * wide;
  float w = wide * (1.0 - jitter * 0.5 + jitter * kh(vec2(r, floor((uv.x + shift) / wide) + seed)));
  float x = (uv.x + shift) / w;
  id = vec2(r, floor(x));
  return vec4(fract(x), fract(uv.y / row), r, w);
}
// marble's veins: thin lines wandering through a warped field, the main ones and finer ones across them
float kveins(vec2 p, float seed) {
  float w = kfbm(p * 1.3 + seed) * 4.0;
  float a = pow(1.0 - abs(sin((p.x * 1.6 + p.y * 0.6 + w) * 3.14159)), 22.0);
  float b = pow(1.0 - abs(sin((p.y * 2.7 - p.x * 1.1 + kfbm(p * 2.6 + seed + 7.0) * 3.0) * 3.14159)), 50.0);
  return clamp(a + 0.6 * b, 0.0, 1.0);
}
// wood's grain along u: its rings' lines (late wood 1, early 0) wandering across v, and its fibres
float kring(vec2 uv, float seed, float rings) {
  float w = kfbm(vec2(uv.x * 0.35, uv.y * 2.0) + seed) * 1.6;
  return smoothstep(0.5, 0.95, fract(uv.y * rings + w + uv.x * 0.04));
}
float kfibre(vec2 uv, float seed) { return kn(vec2(uv.x * 3.0, uv.y * 420.0) + seed) * kfade(0.003); }
// how strongly a cloth's weave shows: a plain weave of threads t metres across, over and under
float kweave(vec2 uv, float t) {
  vec2 q = uv / t;
  float warp = sin(q.x * 3.14159), weft = sin(q.y * 3.14159);
  float over = step(0.0, warp * weft);
  return mix(0.5, mix(0.8, 1.08, over) * (0.85 + 0.15 * abs(over > 0.5 ? weft : warp)), kfade(t * 2.0));
}
// the normal bent by a height field, as three's bump map bends it (perturbNormalArb)
vec3 kitBump(vec3 pos, vec3 n, float h, float faceDirection) {
  vec3 sx = dFdx(pos), sy = dFdy(pos);
  vec3 r1 = cross(sy, n), r2 = cross(n, sx);
  float det = dot(sx, r1) * faceDirection;
  vec2 dh = vec2(dFdx(h), dFdy(h));
  vec3 grad = sign(det) * (dh.x * r1 + dh.y * r2);
  return normalize(abs(det) * n - grad);
}
// a normal in the surface's own ways (u, v, out) turned into the view's, the ways found from the uv's change across
// the pixel, as three's normal map without tangents finds them (getTangentFrame)
vec3 lookPerturb(vec3 n, vec3 nts, float faceDirection) {
  vec3 q0 = dFdx(-vViewPosition), q1 = dFdy(-vViewPosition);
  vec3 q1perp = cross(q1, n), q0perp = cross(n, q0);
  vec3 T = q1perp * lookGx.x + q0perp * lookGy.x;
  vec3 B = q1perp * lookGx.y + q0perp * lookGy.y;
  float det = max(dot(T, T), dot(B, B));
  float scale = det == 0.0 ? 0.0 : faceDirection * inversesqrt(det);
  return normalize(T * (nts.x * scale) + B * (nts.y * scale) + n * nts.z);
}

struct Look {
  vec3 colour; float rough; float metal; float height; vec3 nts; vec3 normal; bool ownNormal;
  float ao; float aoDirect; float alpha; vec3 glow;
  float clearcoat; float clearcoatRough; vec3 sheen; float sheenRough; float iridescence; float iridIor; float iridThick;
  float transmission; float thickness; vec3 attColour; float attDist; float ior; float dispersion;
};
Look lookStart() {
  Look k;
  k.colour = vec3(0.5); k.rough = 0.8; k.metal = 0.0; k.height = 0.0; k.nts = vec3(0.0, 0.0, 1.0);
  k.normal = vec3(0.0, 0.0, 1.0); k.ownNormal = false; k.ao = 1.0; k.aoDirect = 0.0; k.alpha = 1.0; k.glow = vec3(0.0);
  k.clearcoat = 0.0; k.clearcoatRough = 0.1; k.sheen = vec3(0.0); k.sheenRough = 0.5;
  k.iridescence = 0.0; k.iridIor = 1.3; k.iridThick = 400.0;
  k.transmission = 0.0; k.thickness = 0.0; k.attColour = vec3(1.0); k.attDist = 1e9; k.ior = 1.5; k.dispersion = 0.0;
  return k;
}


vec3 p_rgGlow;
vec3 p_rgStone;
float p_rgWidth;
float p_rgStroke;
float p_rgFill;
vec3 p_slColour;
vec3 p_slDeep;
vec3 p_slGlow;
float p_slRuns;
vec3 p_wsDry;
vec3 p_wsWet;
vec3 p_wsSlime;
float p_wsStone;
float p_wsReach;
float p_wsBand;
vec3 p_sgBody;
vec3 p_sgGlow;
vec3 p_sgVein;
float p_sgCells;
float p_sgWidth;
float p_sgVeins;
float p_sgInner;
float p_sgRim;
float p_sgRimWidth;





// the distance from p to the segment a-b
float rgSeg(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  return length(pa - ba * clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0));
}
// a rune: three strokes between points of a 3 by 3 grid, chosen by its number; q in the rune's box, 0 to 1 each way
float rgRune(vec2 q, float id) {
  float d = 9.0;
  for (int s = 0; s < 3; s++) {
    float h = kh(vec2(id, float(s) * 3.7));
    float g = kh(vec2(id * 1.3, float(s) * 5.1 + 1.0));
    vec2 a = vec2(floor(h * 3.0), floor(fract(h * 7.0) * 3.0)) * 0.5;
    vec2 b = vec2(floor(g * 3.0), floor(fract(g * 7.0) * 3.0)) * 0.5;
    if (length(a - b) < 0.1) b = vec2(1.0) - a;
    d = min(d, rgSeg(q, a, b));
  }
  return d;
}





void look_1(inout Look k) {
  p_rgGlow = texelFetch(lookSettings, ivec2(0, 1), 0).rgb;
  p_rgStone = texelFetch(lookSettings, ivec2(1, 1), 0).rgb;
  p_rgWidth = texelFetch(lookSettings, ivec2(2, 1), 0).r;
  p_rgStroke = texelFetch(lookSettings, ivec2(3, 1), 0).r;
  p_rgFill = texelFetch(lookSettings, ivec2(4, 1), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float id = floor(s3.x / p_rgWidth);
    vec2 q = vec2(fract(s3.x / p_rgWidth), (s3.y - 0.5) / p_rgFill + 0.5);
    // a margin round each rune inside its box
    vec2 r = (q - 0.15) / 0.7;
    float inside = step(0.0, r.x) * step(r.x, 1.0) * step(0.0, r.y) * step(r.y, 1.0);
    float d = rgRune(clamp(r, 0.0, 1.0), id);
    float cut = inside * (1.0 - smoothstep(p_rgStroke * 0.7, p_rgStroke, d)) * kfade(p_rgWidth * p_rgStroke * 2.0);
    float any = step(1e-5, abs(s3.x) + abs(s3.y) + abs(s2.x));
    cut *= any;
    float rock = 0.8 + 0.3 * kfbm(uv * 6.0 + seed);
    k.colour = mix(p_rgStone * rock, p_rgGlow * 0.12, cut);
    k.glow = p_rgGlow * cut * clamp(s2.x, 0.0, 1.0) + p_rgGlow * 0.06 * clamp(s2.x, 0.0, 1.0) * inside * any;
    k.rough = mix(0.85, 0.5, cut);
    k.height = -0.002 * cut;

}

void look_2(inout Look k) {
  p_slColour = texelFetch(lookSettings, ivec2(0, 2), 0).rgb;
  p_slDeep = texelFetch(lookSettings, ivec2(1, 2), 0).rgb;
  p_slGlow = texelFetch(lookSettings, ivec2(2, 2), 0).rgb;
  p_slRuns = texelFetch(lookSettings, ivec2(3, 2), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the way down the surface, in the world (y up): the fall of the surface's facing, none on a level surface
    vec3 n = normalize(wn);
    vec3 down = vec3(0.0, -1.0, 0.0) - n * dot(vec3(0.0, -1.0, 0.0), n);
    float steep = length(down);
    down = steep > 1e-3 ? down / steep : vec3(0.0, 0.0, 1.0);
    vec3 across = normalize(cross(n, down));
    vec2 q = vec2(dot(wp, across), dot(wp, down));
    // runs: stretched down the fall where the surface is steep, round blobs where it is level
    vec2 stretch = mix(vec2(1.0, 1.0), vec2(1.0, 0.12), smoothstep(0.1, 0.6, steep));
    float run = kfbm(q * stretch * p_slRuns + seed);
    float lump = kfbm(wp.xz * 9.0 + wp.y * 5.0 + seed);
    float thick = smoothstep(0.35, 0.75, run);
    k.colour = mix(p_slDeep, p_slColour, 0.4 + 0.6 * thick) * (0.85 + 0.3 * lump);
    k.glow = p_slGlow * (0.5 + thick);
    k.rough = mix(0.25, 0.06, thick);
    k.clearcoat = 1.0;
    k.clearcoatRough = 0.08;
    k.height = 0.004 * thick + 0.002 * lump;

}

void look_3(inout Look k) {
  p_wsDry = texelFetch(lookSettings, ivec2(0, 3), 0).rgb;
  p_wsWet = texelFetch(lookSettings, ivec2(1, 3), 0).rgb;
  p_wsSlime = texelFetch(lookSettings, ivec2(2, 3), 0).rgb;
  p_wsStone = texelFetch(lookSettings, ivec2(3, 3), 0).r;
  p_wsReach = texelFetch(lookSettings, ivec2(4, 3), 0).r;
  p_wsBand = texelFetch(lookSettings, ivec2(5, 3), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float id, edge;
    float d = kvor(uv / p_wsStone, id, edge);
    float joint = (1.0 - smoothstep(0.02, 0.07, edge)) * kfade(p_wsStone * 0.2);
    float grain = kfbm(uv * 14.0 + seed + id * 7.0);
    vec3 dry = p_wsDry * (0.82 + 0.25 * fract(id * 13.7)) * (0.85 + 0.3 * grain);
    float h = s3.x;
    // soaked from the water up, the soak creeping higher in the joints
    float wet = 1.0 - smoothstep(0.0, p_wsReach * (1.0 + 0.6 * joint), h + 0.03 * (grain - 0.5) * p_wsReach * 4.0);
    // the slime: a ragged band along the waterline, reaching higher on some stones and in the joints, thinning out
    // under the water
    float reach = p_wsBand * (0.5 + 0.9 * fract(id * 31.1) + 0.8 * joint) + 0.04 * (kfbm(uv * 9.0 + seed) - 0.5);
    float slime = (1.0 - smoothstep(reach * 0.7, reach, h)) * smoothstep(-0.2, -0.05, h);
    vec3 col = mix(dry, p_wsWet * (0.85 + 0.3 * grain), wet);
    col = mix(col, p_wsSlime * (0.8 + 0.5 * grain), slime * 0.9);
    col *= 1.0 - 0.45 * joint;
    k.colour = col;
    k.rough = mix(mix(0.88, 0.5, wet), 0.3, slime);
    k.clearcoat = 0.3 * wet;
    k.clearcoatRough = 0.3;
    k.height = 0.004 * (grain - 0.5) - 0.006 * joint;
    k.ao = 1.0 - 0.4 * joint;

}

void look_4(inout Look k) {

  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec3 c = vec3(0.55, 0.52, 0.46) * (0.88 + 0.2 * kfbm(uv * 5.0 + seed));
    float stain = smoothstep(0.5, 0.85, kfbm(vec2(uv.x * 4.0, wp.y * 0.6) + seed)) * (1.0 - smoothstep(0.0, 0.5, wn.y));
    float lich = smoothstep(0.62, 0.8, kfbm(uv * 4.0 + seed + 3.0));
    float salt = smoothstep(0.7, 0.9, kfbm(uv * 6.0 + seed + 8.0)) * (1.0 - smoothstep(0.2, 0.8, wp.y));
    float moss = smoothstep(0.6, 0.8, kfbm(uv * 3.0 + seed + 6.0)) * smoothstep(0.4, 0.9, wn.y);
    float soot = smoothstep(0.65, 0.9, kfbm(uv * 1.5 + seed + 11.0));
    c = mix(c, c * vec3(0.55, 0.52, 0.5), stain);
    c = mix(c, vec3(0.72, 0.62, 0.25), lich * 0.7);
    c = mix(c, vec3(0.85, 0.84, 0.8), salt * 0.7);
    c = mix(c, vec3(0.1, 0.18, 0.04), moss);
    k.colour = mix(c, vec3(0.06, 0.055, 0.05), soot * 0.7);
    k.rough = 0.95;
    k.height = 0.002 * (kfbm(uv * 12.0 + seed) - 0.5) + 0.001 * lich + 0.002 * moss;

}

void look_5(inout Look k) {
  p_sgBody = texelFetch(lookSettings, ivec2(0, 5), 0).rgb;
  p_sgGlow = texelFetch(lookSettings, ivec2(1, 5), 0).rgb;
  p_sgVein = texelFetch(lookSettings, ivec2(2, 5), 0).rgb;
  p_sgCells = texelFetch(lookSettings, ivec2(3, 5), 0).r;
  p_sgWidth = texelFetch(lookSettings, ivec2(4, 5), 0).r;
  p_sgVeins = texelFetch(lookSettings, ivec2(5, 5), 0).r;
  p_sgInner = texelFetch(lookSettings, ivec2(6, 5), 0).r;
  p_sgRim = texelFetch(lookSettings, ivec2(7, 5), 0).r;
  p_sgRimWidth = texelFetch(lookSettings, ivec2(8, 5), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the cells' edges: the veins, faded where a vein is finer than a pixel
    float sgId, sgEdge;
    kvor(uv * p_sgCells + seed, sgId, sgEdge);
    float sgLine = 1.0 - smoothstep(0.0, p_sgWidth, sgEdge);
    sgLine *= kfade(p_sgWidth / p_sgCells);
    // each cell a little brighter or dimmer than the next, and the body breathing over its length
    float sgCell = 0.75 + 0.5 * kh1(sgId);
    float sgDrift = 0.8 + 0.4 * kfbm(uv * 1.5 + seed);
    // the rim: brighter where the surface turns away from the eye
    float sgFacing = abs(dot(normalize(vNormal), normalize(vViewPosition)));
    float sgRimLight = pow(1.0 - sgFacing, p_sgRimWidth);
    k.colour = p_sgBody * (0.85 + 0.15 * sgDrift);
    k.glow = p_sgGlow * (p_sgInner * sgDrift * sgCell + p_sgRim * sgRimLight) + p_sgVein * p_sgVeins * sgLine * sgCell;
    k.rough = 0.35;
    k.height = 0.0015 * sgLine;

}






Look lookRun(int id) {
  Look k = lookStart();
  switch (id) {
    case 1: look_1(k); break;
    case 2: look_2(k); break;
    case 3: look_3(k); break;
    case 4: look_4(k); break;
    case 5: look_5(k); break;
  }
  if (lookDebug > 0.5) {
    switch (id) {
      case 1: k.colour = vec3(0.042311410620809675, 0.38132601143253014, 1.0); break;
      case 2: k.colour = vec3(0.07818742180518633, 0.38132601143253014, 0.010329823029626936); break;
      case 3: k.colour = vec3(0.06847816984440017, 0.10224173308810132, 0.08437621154414882); break;
      case 4: k.colour = vec3(0.7912979403326302, 0.019382360956935723, 0.046665086336880095); break;
      case 5: k.colour = vec3(0.3467040563550296, 0.6866853124353135, 1.0); break;
    }
  }
  return k;
}
float lookShadow(int id, vec3 Lview) {

  return 1.0;
}

