    float moss = smoothstep(0.6, 0.8, kfbm(uv * 3.0 + seed + 6.0)) * smoothstep(0.4, 0.9, wn.y);
    float soot = smoothstep(0.65, 0.9, kfbm(uv * 1.5 + seed + 11.0));
    c = mix(c, c * vec3(0.55, 0.52, 0.5), stain);
    c = mix(c, vec3(0.72, 0.62, 0.25), lich * 0.7);
    c = mix(c, vec3(0.85, 0.84, 0.8), salt * 0.7);
    c = mix(c, vec3(0.1, 0.18, 0.04), moss);
    k.colour = mix(c, vec3(0.06, 0.055, 0.05), soot * 0.7);
    k.rough = 0.95;
    k.height = 0.002 * (kfbm(uv * 12.0 + seed) - 0.5) + 0.001 * lich + 0.002 * moss;

}

void look_5(inout Look k) {
  p_sgBody = texelFetch(lookSettings, ivec2(0, 5), 0).rgb;
  p_sgGlow = texelFetch(lookSettings, ivec2(1, 5), 0).rgb;
  p_sgVein = texelFetch(lookSettings, ivec2(2, 5), 0).rgb;
  p_sgCells = texelFetch(lookSettings, ivec2(3, 5), 0).r;
  p_sgWidth = texelFetch(lookSettings, ivec2(4, 5), 0).r;
  p_sgVeins = texelFetch(lookSettings, ivec2(5, 5), 0).r;
  p_sgInner = texelFetch(lookSettings, ivec2(6, 5), 0).r;
  p_sgRim = texelFetch(lookSettings, ivec2(7, 5), 0).r;
  p_sgRimWidth = texelFetch(lookSettings, ivec2(8, 5), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the cells' edges: the veins, faded where a vein is finer than a pixel
    float sgId, sgEdge;
    kvor(uv * p_sgCells + seed, sgId, sgEdge);
    float sgLine = 1.0 - smoothstep(0.0, p_sgWidth, sgEdge);
    sgLine *= kfade(p_sgWidth / p_sgCells);
    // each cell a little brighter or dimmer than the next, and the body breathing over its length
    float sgCell = 0.75 + 0.5 * kh1(sgId);
    float sgDrift = 0.8 + 0.4 * kfbm(uv * 1.5 + seed);
    // the rim: brighter where the surface turns away from the eye
    float sgFacing = abs(dot(normalize(vNormal), normalize(vViewPosition)));
    float sgRimLight = pow(1.0 - sgFacing, p_sgRimWidth);
    k.colour = p_sgBody * (0.85 + 0.15 * sgDrift);
    k.glow = p_sgGlow * (p_sgInner * sgDrift * sgCell + p_sgRim * sgRimLight) + p_sgVein * p_sgVeins * sgLine * sgCell;
    k.rough = 0.35;
    k.height = 0.0015 * sgLine;

}







